 CREATE OR REPLACE FUNCTION public.addprovlicensinginfo(insertobj json)                                                                                                                                                                                
  RETURNS text                                                                                                                                                                                                                                         
  LANGUAGE plpgsql                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                         
 declare                                                                                                                                                                                                                                               
 v_provider_id character varying;                                                                                                                                                                                                                      
 v_license_no character varying;                                                                                                                                                                                                                       
 v_securityuserid character varying;                                                                                                                                                                                                                   
 v_applicant_id character varying;                                                                                                                                                                                                                     
 v_minageno int;                                                                                                                                                                                                                                       
 v_maxageno int;                                                                                                                                                                                                                                       
 v_gender_cd character varying;                                                                                                                                                                                                                        
 v_childrenno int;                                                                                                                                                                                                                                     
 v_minagemonthno int;                                                                                                                                                                                                                                  
 v_maxagemonthno int;                                                                                                                                                                                                                                  
 v_effectivedate date;                                                                                                                                                                                                                                 
 v_enddate date;                                                                                                                                                                                                                                       
 v_parentproviderid int;                                                                                                                                                                                                                               
 v_prgram text;                                                                                                                                                                                                                                        
 v_programtype text;                                                                                                                                                                                                                                   
 v_licencetypecd text;                                                                                                                                                                                                                                 
 v_licappid int;                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                       
 begin                                                                                                                                                                                                                                                 
 v_license_no := insertobj->>'license_no';                                                                                                                                                                                                             
 v_provider_id := insertobj->>'provider_id';                                                                                                                                                                                                           
 v_securityuserid := insertobj->>'securityuserid';                                                                                                                                                                                                     
 v_applicant_id := insertobj->>'applicant_id';                                                                                                                                                                                                         
                                                                                                                                                                                                                                                       
 SELECT paa.minimum_age_no ,paa.maximum_age_no, paa.gender_cd, paa.children_no, paa.min_age_months_no , paa.max_age_months_no                                                                                                                          
 into v_minageno, v_maxageno, v_gender_cd, v_childrenno, v_minagemonthno, v_maxagemonthno                                                                                                                                                              
 FROM tb_prov_applicant_accomodation paa where provider_applicant_id = v_applicant_id ;                                                                                                                                                                
                                                                                                                                                                                                                                                       
 select requested_license_effective_date,requested_license_end_date, provider_id , prgram , program_type into v_effectivedate, v_enddate , v_parentproviderid , v_prgram, v_programtype from tb_provider_applicant where applicant_id = v_applicant_id;
                                                                                                                                                                                                                                                       
 select picklist_value_cd into v_licencetypecd from tb_picklist_values where picklist_type_id = 284 and value_tx = v_programtype ;                                                                                                                     
                                                                                                                                                                                                                                                       
 INSERT INTO tb_provider_licensing                                                                                                                                                                                                                     
 (site_id, provider_id, license_type_cd, license_status_cd, application_type_cd, license_decision_cd,                                                                                                                                                  
 license_issue_dt, license_expiry_dt, license_modification_dt, license_no, licensing_agency_cd, licensing_corodinator_id, licensed_beds_no, requirement_sw, midterm_issue_dt, active_sw, comments_tx, program_id,                                      
 revoke_dt, revoke_approval_status_cd, midterm_rqrmnt_sw, create_ts, create_user_id, update_ts, update_user_id, delete_sw, ref_license_application_id, lic_entry_dt, request_revoke_sw, pre_revoke_status_cd , license_type ,license_level)            
 VALUES((v_provider_id)::int, v_parentproviderid, v_licencetypecd , '3263', '3068', '3263',v_effectivedate, v_enddate, NULL, v_license_no, '', 0, 0, '', NULL, '', '', 0, NULL, '', '', now(), v_securityuserid, now(),                                
 v_securityuserid, 'N'::bpchar, 0, NULL, '', '',v_programtype,v_prgram) returning license_application_id into v_licappid;                                                                                                                              
                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                       
 INSERT INTO tb_prov_accomodation                                                                                                                                                                                                                      
 (prov_accomodation_id, license_application_id, minimum_age_no, maximum_age_no, gender_cd, children_no, create_ts, create_user_id, update_ts, update_user_id, delete_sw, min_age_months_no, max_age_months_no)                                         
 VALUES(gen_random_uuid(), v_licappid, v_minageno, v_maxageno, v_gender_cd, v_childrenno, now(), v_securityuserid, now(), v_securityuserid, 'N'::bpchar, v_minagemonthno, v_maxagemonthno);                                                            
                                                                                                                                                                                                                                                       
 update tb_provider_applicant set license_no = v_license_no where applicant_id = v_applicant_id;                                                                                                                                                       
                                                                                                                                                                                                                                                       
 return 'success';                                                                                                                                                                                                                                     
 end                                                                                                                                                                                                                                                   
 $function$                                                                                                                                                                                                                                            

